from kivy.app import App
from kivy.uix.widget import Widget
from kivy.uix.button import Button
from kivy.uix.gridlayout import GridLayout
from kivy.uix.behaviors import FocusBehavior, CompoundSelectionBehavior
from kivy.core.window import Window
from kivy.properties import ListProperty, BooleanProperty

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    """Custom grid that supports selection, navigation, and touch handling."""

    selected_nodes = ListProperty([])
    _current_input = ""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.cols = 8  # 8 columns for a nice layout
        self.rows = 5  # 5 rows for 40 buttons
        self.padding = 10
        self.spacing = 10
        self.size_hint = (1, 1)
        self.bind(selected_nodes=self.on_selection_change)

        # Create 40 buttons
        for i in range(40):
            btn = Button(text=str(i + 1), font_size=16)
            btn.bind(on_touch_down=self.on_button_touch_down)
            self.add_widget(btn)

    def on_selection_change(self, instance, value):
        """Print selected nodes when selection changes."""
        print(f"Selected nodes: {self.selected_nodes}")

    def on_key_down(self, key, scancode=None, codepoint=None, text=None, modifiers=None):
        """Handle key down events for navigation and selection."""
        if text and text.isdigit():
            self._current_input += text
            # Try to navigate to node by number
            try:
                target_num = int(self._current_input) - 1  # Convert to 0-based index
                if 0 <= target_num < len(self.children):
                    self.select_node(target_num)
                    self._current_input = ""
                else:
                    # If number is too large, clear input
                    self._current_input = ""
            except:
                pass
        elif key == 8:  # Backspace
            self._current_input = self._current_input[:-1]
        elif key == 13:  # Enter
            if self._current_input:
                try:
                    target_num = int(self._current_input) - 1
                    if 0 <= target_num < len(self.children):
                        self.select_node(target_num)
                        self._current_input = ""
                except:
                    pass
        return True

    def on_key_up(self, key, scancode=None, codepoint=None, text=None, modifiers=None):
        """Handle key up events."""
        return True

    def select_node(self, index):
        """Select a node by index."""
        if 0 <= index < len(self.children):
            btn = self.children[index]
            if btn in self.selected_nodes:
                self.deselect_node(index)
            else:
                self.select_node_by_index(index)

    def select_node_by_index(self, index):
        """Select a node by index and change its background color."""
        if 0 <= index < len(self.children):
            btn = self.children[index]
            btn.background_color = (0.2, 0.6, 1, 1)  # Blue background
            self.select_with_touch(btn, True)

    def deselect_node(self, index):
        """Deselect a node by index and reset its background color."""
        if 0 <= index < len(self.children):
            btn = self.children[index]
            btn.background_color = (1, 1, 1, 1)  # Default white background
            self.deselect_with_touch(btn, True)

    def on_button_touch_down(self, instance, touch):
        """Handle touch down on a button."""
        if instance.collide_point(*touch.pos):
            # Use the compound selection behavior
            if touch.is_double_tap:
                # Double tap selects/deselects
                if instance in self.selected_nodes:
                    self.deselect_node(self.children.index(instance))
                else:
                    self.select_node_by_index(self.children.index(instance))
            else:
                # Single tap selects
                self.select_node_by_index(self.children.index(instance))
            return True
        return False

    def on_touch_down(self, touch):
        """Override touch down to handle grid-level touch events."""
        if super().on_touch_down(touch):
            return True
        return False

    def on_touch_up(self, touch):
        """Override touch up to handle grid-level touch events."""
        if super().on_touch_up(touch):
            return True
        return False


class SelectableGridApp(App):
    """Main application class."""

    def build(self):
        # Create the grid with specific parameters
        grid = SelectableGrid(cols=8, rows=5, padding=10, spacing=10)

        # Bind the touch down event of each button to the grid's touch handling
        # This is already handled in the button creation loop above

        # Set the grid as the root widget
        return grid


