class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    """Custom grid that supports selection, navigation, and touch handling."""

    selected_nodes = ListProperty([])
    _current_input = ""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.cols = 8  # 8 columns for a nice layout
        self.rows = 5  # 5 rows for 40 buttons
        self.padding = 10
        self.spacing = 10
        self.size_hint = (1, 1)
        self.bind(selected_nodes=self.on_selection_change)

        # Create 40 buttons
        for i in range(40):
            btn = Button(text=str(i + 1), font_size=16)
            btn.bind(on_touch_down=self.on_button_touch_down)
            self.add_widget(btn)

    def on_selection_change(self, instance, value):
        """Print selected nodes when selection changes."""
        print(f"Selected nodes: {self.selected_nodes}")

    def on_key_down(self, key, scancode=None, codepoint=None, text=None, modifiers=None):
        """Handle key down events for navigation and selection."""
        if text and text.isdigit():
            self._current_input += text
            # Try to navigate to node by number
            try:
                target_num = int(self._current_input) - 1  # Convert to 0-based index
                if 0 <= target_num < len(self.children):
                    self.select_node(target_num)
                    self._current_input = ""
                else:
                    # If number is too large, clear input
                    self._current_input = ""
            except:
                pass
        elif key == 8:  # Backspace
            self._current_input = self._current_input[:-1]
        elif key == 13:  # Enter
            if self._current_input:
                try:
                    target_num = int(self._current_input) - 1
                    if 0 <= target_num < len(self.children):
                        self.select_node(target_num)
                        self._current_input = ""
                except:
                    pass
        return True

    def on_key_up(self, key, scancode=None, codepoint=None, text=None, modifiers=None):
        """Handle key up events."""
        return True

    def select_node(self, index):
        """Select a node by index."""
        if 0 <= index < len(self.children):
            btn = self.children[index]
            if btn in self.selected_nodes:
                self.deselect_node(index)
            else:
