SERVICE_PORT = 80
TARGET_PORT = 80
INGRESS_HOST = "myapp.example.com"
INGRESS_PATH = "/"

def create_deployment(api_client):
    """
    Create a Kubernetes Deployment with a container using the specified image and port.
    """
    deployment = client.V1Deployment(
        metadata=client.V1ObjectMeta(name=DEPLOYMENT_NAME),
        spec=client.V1DeploymentSpec(
            replicas=2,
            selector=client.V1LabelSelector(
                match_labels={"app": "my-app"}
            ),
            template=client.V1PodTemplateSpec(
                metadata=client.V1ObjectMeta(
                    labels={"app": "my-app"}
                ),
                spec=client.V1PodSpec(
                    containers=[
                        client.V1Container(
                            name="my-app-container",
                            image=IMAGE_NAME,
                            ports=[client.V1ContainerPort(container_port=CONTAINER_PORT)]
                        )
                    ]
                )
            )
        )
    )

    try:
        api_client.apps_v1.create_namespaced_deployment(
            namespace=NAMESPACE,
            body=deployment
        )
        print(f"Deployment {DEPLOYMENT_NAME} created successfully.")
    except ApiException as e:
        print(f"Exception when creating deployment: {e}")
        raise

def create_service(api_client):
    """
    Create a Kubernetes Service to expose the Deployment on a specific port.
    """
    service = client.V1Service(
        metadata=client.V1ObjectMeta(name=SERVICE_NAME),
        spec=client.V1ServiceSpec(
            selector={"app": "my-app"},
            ports=[client.V1ServicePort(
                port=SERVICE_PORT,
                target_port=TARGET_PORT,
                protocol="TCP"
            )],
            type="ClusterIP"
        )
    )

    try:
        api_client.core_v1.create_namespaced_service(
            namespace=NAMESPACE,
            body=service
        )
        print(f"Service {SERVICE_NAME} created successfully.")
    except ApiException as e:
        print(f"Exception when creating service: {e}")
        raise

def create_ingress(api_client):
    """
    Create a Kubernetes Ingress to expose the service externally via a host and path.
    """
    # Ensure the ingress class is specified (adjust if needed)
    ingress_class = "nginx"  # Common ingress class; adjust based on your cluster

    ingress = client.NetworkingV1Ingress(
        metadata=client.V1ObjectMeta(
            name=INGRESS_NAME,
            annotations={
                "kubernetes.io/ingress.class": ingress_class
            }
        ),
        spec=client.NetworkingV1IngressSpec(
            rules=[
                client.NetworkingV1IngressRule(
                    host=INGRESS_HOST,
                    http=client.NetworkingV1HTTPIngressRuleValue(
                        paths=[
                            client.NetworkingV1HTTPIngressPath(
                                path=INGRESS_PATH,
                                path_type="Prefix",
                                backend=client.NetworkingV1IngressBackend(
                                    service=client.NetworkingV1IngressServiceBackend(
                                        name=SERVICE_NAME,
                                        port=client.NetworkingV1ServiceBackendPort(
                                            number=SERVICE_PORT
                                        )
                                    )
                                )
                            )
                        ]
                    )
                )
            ]
        )
    )

    try:
        api_client.networking_v1.create_namespaced_ingress(
            namespace=NAMESPACE,
            body=ingress
        )
        print(f"Ingress {INGRESS_NAME} created successfully.")
    except ApiException as e:
        print(f"Exception when creating ingress: {e}")
        raise

def main():
    """
    Main function to load Kubernetes configuration and create deployment, service, and ingress.
    """
    print("Loading Kubernetes configuration...")

    # Load the kubeconfig file (default: ~/.kube/config)
    try:
        config.load_kube_config()
    except Exception as e:
        print(f"Failed to load kubeconfig: {e}")
        print("Trying to use in-cluster configuration...")
        try:
            config.load_incluster_config()
        except Exception as e:
            print(f"Failed to load in-cluster config: {e}")
            raise

    print("Kubernetes configuration loaded successfully.")

    # Create API clients
    apps_v1 = client.AppsV1Api()
    core_v1 = client.CoreV1Api()
    networking_v1 = client.NetworkingV1Api()

    # Create resources in order
    print("Creating deployment...")
    create_deployment(apps_v1)

    print("Creating service...")
    create_service(core_v1)

    print("Creating ingress...")
    create_ingress(networking_v1)

    print("All resources created successfully!")

if __name__ == "__main__":
    main()
